import{_ as e,a as o,o as a,a4 as n}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse(`{"title":"Add to Cart","description":"","frontmatter":{"outline":false,"examples":[{"id":"add-simple","title":"Simple / Virtual","description":"Add a simple or virtual product. Only productId and quantity are needed.","request":"POST /api/shop/add-product-in-cart\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\nAuthorization: Bearer <cartToken>\\n\\n{\\n  \\"productId\\": 1,\\n  \\"quantity\\": 2\\n}\\n","response":"{\\n  \\"id\\": 6698,\\n  \\"cartToken\\": \\"6698\\",\\n  \\"customerId\\": null,\\n  \\"channelId\\": 1,\\n  \\"itemsCount\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"id\\": 7567,\\n      \\"cartId\\": 6698,\\n      \\"productId\\": 1,\\n      \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n      \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n      \\"quantity\\": 2,\\n      \\"price\\": 100,\\n      \\"basePrice\\": 100,\\n      \\"total\\": 200,\\n      \\"baseTotal\\": 200,\\n      \\"type\\": \\"simple\\",\\n      \\"options\\": null,\\n      \\"formattedPrice\\": \\"$100.00\\",\\n      \\"formattedTotal\\": \\"$200.00\\",\\n      \\"canChangeQty\\": true\\n    }\\n  ],\\n  \\"subtotal\\": 200,\\n  \\"grandTotal\\": 200,\\n  \\"formattedSubtotal\\": \\"$200.00\\",\\n  \\"formattedGrandTotal\\": \\"$200.00\\",\\n  \\"couponCode\\": null,\\n  \\"success\\": true,\\n  \\"message\\": \\"Product added to cart successfully.\\"\\n}\\n"},{"id":"add-configurable","title":"Configurable","description":"Add a configurable product. Pass the chosen variant's product ID in selectedConfigurableOption (this field is required).","request":"POST /api/shop/add-product-in-cart\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\nAuthorization: Bearer <cartToken>\\n\\n{\\n  \\"productId\\": 123,\\n  \\"quantity\\": 1,\\n  \\"selectedConfigurableOption\\": 124\\n}\\n","response":"{\\n  \\"id\\": 6699,\\n  \\"itemsCount\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"id\\": 7568,\\n      \\"productId\\": 123,\\n      \\"name\\": \\"Zoe Tank\\",\\n      \\"quantity\\": 1,\\n      \\"type\\": \\"configurable\\",\\n      \\"options\\": [\\n        { \\"attribute_name\\": \\"Size\\", \\"option_label\\": \\"S\\" },\\n        { \\"attribute_name\\": \\"Color\\", \\"option_label\\": \\"Red\\" }\\n      ],\\n      \\"formattedTotal\\": \\"$2,040.00\\"\\n    }\\n  ],\\n  \\"grandTotal\\": 2040,\\n  \\"formattedGrandTotal\\": \\"$2,040.00\\",\\n  \\"success\\": true,\\n  \\"message\\": \\"Product added to cart successfully.\\"\\n}\\n"},{"id":"add-bundle","title":"Bundle","description":"Add a bundle product. bundleOptions maps each bundle option ID to the chosen bundle-option-product IDs; bundleOptionQty maps each option ID to its quantity.","request":"POST /api/shop/add-product-in-cart\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\nAuthorization: Bearer <cartToken>\\n\\n{\\n  \\"productId\\": 2517,\\n  \\"quantity\\": 1,\\n  \\"bundleOptions\\": {\\n    \\"1\\": [1],\\n    \\"2\\": [2],\\n    \\"3\\": [3],\\n    \\"4\\": [4]\\n  },\\n  \\"bundleOptionQty\\": {\\n    \\"1\\": 1,\\n    \\"2\\": 1,\\n    \\"3\\": 1,\\n    \\"4\\": 1\\n  }\\n}\\n","response":"{\\n  \\"id\\": 6700,\\n  \\"itemsCount\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"productId\\": 2517,\\n      \\"name\\": \\"Arctic Frost Winter Accessories\\",\\n      \\"quantity\\": 1,\\n      \\"type\\": \\"bundle\\",\\n      \\"formattedTotal\\": \\"$69.00\\"\\n    }\\n  ],\\n  \\"grandTotal\\": 69,\\n  \\"formattedGrandTotal\\": \\"$69.00\\",\\n  \\"success\\": true,\\n  \\"message\\": \\"Product added to cart successfully.\\"\\n}\\n"},{"id":"add-grouped","title":"Grouped","description":"Add a grouped product. groupedQty maps each associated product ID to its quantity (include every associated product).","request":"POST /api/shop/add-product-in-cart\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\nAuthorization: Bearer <cartToken>\\n\\n{\\n  \\"productId\\": 2516,\\n  \\"quantity\\": 1,\\n  \\"groupedQty\\": {\\n    \\"2512\\": 1,\\n    \\"2514\\": 2,\\n    \\"2515\\": 1\\n  }\\n}\\n","response":"{\\n  \\"id\\": 6701,\\n  \\"itemsCount\\": 3,\\n  \\"items\\": [\\n    { \\"productId\\": 2512, \\"type\\": \\"simple\\", \\"quantity\\": 1 },\\n    { \\"productId\\": 2514, \\"type\\": \\"simple\\", \\"quantity\\": 2 },\\n    { \\"productId\\": 2515, \\"type\\": \\"simple\\", \\"quantity\\": 1 }\\n  ],\\n  \\"success\\": true,\\n  \\"message\\": \\"Product added to cart successfully.\\"\\n}\\n"},{"id":"add-downloadable","title":"Downloadable","description":"Add a downloadable product. links is the array of selected download-link IDs.","request":"POST /api/shop/add-product-in-cart\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\nAuthorization: Bearer <cartToken>\\n\\n{\\n  \\"productId\\": 2506,\\n  \\"quantity\\": 1,\\n  \\"links\\": [2]\\n}\\n","response":"{\\n  \\"id\\": 6702,\\n  \\"itemsCount\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"productId\\": 2506,\\n      \\"name\\": \\"Complete Personal Finance Guide\\",\\n      \\"quantity\\": 1,\\n      \\"type\\": \\"downloadable\\",\\n      \\"options\\": [\\n        {\\n          \\"option_id\\": 0,\\n          \\"option_label\\": \\"Full eBook PDF\\",\\n          \\"attribute_name\\": \\"Downloads\\"\\n        }\\n      ],\\n      \\"formattedTotal\\": \\"$18.00\\"\\n    }\\n  ],\\n  \\"grandTotal\\": 18,\\n  \\"formattedGrandTotal\\": \\"$18.00\\",\\n  \\"success\\": true,\\n  \\"message\\": \\"Product added to cart successfully.\\"\\n}\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing cart/customer token","solution":"Create a guest cart with POST /api/shop/cart-tokens and send its cartToken as a Bearer token (or log a customer in and send their token)."},{"error":"400 Bad Request","cause":"An inactive or out-of-stock item was requested (e.g. a grouped/bundle child)","solution":"Choose products that are active and in stock."},{"error":"422 Validation Error","cause":"Quantity below 1, or required options missing for the product type","solution":"Send a valid quantity and the option fields required by the product type (see below)."}]},{"id":"add-customizable","title":"Simple Product - Customizable Options","description":"Add a product with customizable options. Options 9 and 10 are selects (value ids). Option 11 is a file type — its value is a token from the upload endpoint (upload the file first, then pass the token). See the Customizable options section below.","request":"POST /api/shop/add-product-in-cart\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\nAuthorization: Bearer <token>\\n\\n{\\n  \\"productId\\": 2977,\\n  \\"quantity\\": 1,\\n  \\"customizableOptions\\": {\\n    \\"9\\": [9],\\n    \\"10\\": [12],\\n    \\"11\\": [\\"<token-from-upload-endpoint>\\"]\\n  }\\n}\\n","response":"{\\n  \\"id\\": 6895,\\n  \\"cartToken\\": \\"6895\\",\\n  \\"customerId\\": 19,\\n  \\"channelId\\": 1,\\n  \\"itemsCount\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"id\\": 7769,\\n      \\"cartId\\": 6895,\\n      \\"productId\\": 2977,\\n      \\"name\\": \\"Simple Customizable options\\",\\n      \\"sku\\": \\"testcustomizeoption\\",\\n      \\"quantity\\": 1,\\n      \\"price\\": 54,\\n      \\"total\\": 54,\\n      \\"type\\": \\"simple\\",\\n      \\"options\\": [\\n        {\\n          \\"option_label\\": \\"1kg\\",\\n          \\"attribute_name\\": \\"Weight Select\\",\\n          \\"attribute_type\\": \\"select\\"\\n        },\\n        {\\n          \\"option_label\\": \\"Pineapple\\",\\n          \\"attribute_name\\": \\"Flavour\\",\\n          \\"attribute_type\\": \\"select\\"\\n        }\\n      ],\\n      \\"formattedPrice\\": \\"$54.00\\",\\n      \\"formattedTotal\\": \\"$54.00\\",\\n      \\"canChangeQty\\": true\\n    }\\n  ],\\n  \\"subtotal\\": 54,\\n  \\"grandTotal\\": 54,\\n  \\"formattedSubtotal\\": \\"$54.00\\",\\n  \\"formattedGrandTotal\\": \\"$54.00\\",\\n  \\"couponCode\\": null,\\n  \\"success\\": true,\\n  \\"message\\": \\"Product added to cart successfully.\\"\\n}\\n","commonErrors":[{"error":"422 Validation Error","cause":"A required customizable option was omitted","solution":"Include every option whose isRequired is true (from the product's customizableOptions)"}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/add-to-cart.md","filePath":"api/rest-api/shop/cart/add-to-cart.md","lastUpdated":1784902076000}`),d={name:"api/rest-api/shop/cart/add-to-cart.md"};function i(s,t,r,c,l,p){return a(),o("div",null,t[0]||(t[0]=[n('<h1 id="add-to-cart" tabindex="-1">Add to Cart <a class="header-anchor" href="#add-to-cart" aria-label="Permalink to &quot;Add to Cart&quot;">​</a></h1><p>Add a product to the shopping cart. The request body depends on the <strong>product type</strong> — simple and virtual need only <code>productId</code> + <code>quantity</code>, while configurable, bundle, grouped, and downloadable products require their option selections.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/add-product-in-cart</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint operates on a specific cart, so every request needs a <strong>cart token</strong> (Bearer), in addition to the storefront key:</p><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td><code>Bearer &lt;token&gt;</code> — a guest <strong>cart token</strong> or a logged-in <strong>customer token</strong></td></tr><tr><td><code>Content-Type</code></td><td>Yes</td><td><code>application/json</code></td></tr></tbody></table><p>Get a guest cart token first with <a href="/api/rest-api/shop/cart/create-cart.html">Create Cart</a> (<code>POST /api/shop/cart-tokens</code>) — its <code>cartToken</code> is the Bearer value. For a logged-in customer, use the token from <a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a>.</p><h2 id="request-body-by-product-type" tabindex="-1">Request body by product type <a class="header-anchor" href="#request-body-by-product-type" aria-label="Permalink to &quot;Request body by product type&quot;">​</a></h2><p>All types take <code>productId</code> and <code>quantity</code>. Add the fields for the product&#39;s type:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Applies to</th><th>Description</th></tr></thead><tbody><tr><td><code>productId</code></td><td>integer</td><td>all</td><td>The product ID being added</td></tr><tr><td><code>quantity</code></td><td>integer</td><td>all</td><td>Quantity (minimum 1)</td></tr><tr><td><code>selectedConfigurableOption</code></td><td>integer</td><td>configurable</td><td><strong>Required.</strong> The chosen <strong>variant</strong> product ID.</td></tr><tr><td><code>superAttribute</code></td><td>object</td><td>configurable</td><td><code>{ &quot;&lt;attributeId&gt;&quot;: &lt;optionId&gt; }</code>. Accepted but <strong>not used by add-to-cart</strong> — the cart resolves the variant from <code>selectedConfigurableOption</code>, so always send that.</td></tr><tr><td><code>bundleOptions</code></td><td>object</td><td>bundle</td><td><code>{ &quot;&lt;optionId&gt;&quot;: [&lt;bundleOptionProductId&gt;, …] }</code> — the <strong>bundle-option-product IDs</strong> (from the product detail), not raw product IDs.</td></tr><tr><td><code>bundleOptionQty</code></td><td>object</td><td>bundle</td><td><code>{ &quot;&lt;optionId&gt;&quot;: &lt;qty&gt; }</code> — quantity per bundle option</td></tr><tr><td><code>groupedQty</code></td><td>object</td><td>grouped</td><td><code>{ &quot;&lt;associatedProductId&gt;&quot;: &lt;qty&gt; }</code> — include every associated product</td></tr><tr><td><code>links</code></td><td>array</td><td>downloadable</td><td><code>[&lt;linkId&gt;, …]</code> — selected download-link IDs</td></tr><tr><td><code>customizableOptions</code></td><td>object</td><td>simple / virtual / downloadable</td><td><code>{ &quot;&lt;optionId&gt;&quot;: [&lt;valueId&gt;, …] }</code> — chosen customizable-option values. See below.</td></tr></tbody></table><p>The option IDs (variant product IDs, bundle-option-product IDs, associated product IDs, link IDs) come from the <strong>product detail</strong> response — fetch the product first to discover them. The product, variant, and bundle-option products must be <strong>active and in stock</strong>, or the item is rejected.</p><h3 id="customizable-options" tabindex="-1">Customizable options <a class="header-anchor" href="#customizable-options" aria-label="Permalink to &quot;Customizable options&quot;">​</a></h3><p>Customizable options are extra inputs an admin attaches to a product (a weight dropdown, a flavour picker, an engraving text field). They are <strong>not</strong> limited to configurable products — a <strong>simple or virtual</strong> product can carry them. Read them from the product&#39;s <code>customizableOptions</code> (<a href="/api/rest-api/shop/products/get-product.html">Get Product</a>): each option has an <code>id</code> and a <code>prices</code> array whose entries each have an <code>id</code> (the value id), and <code>isRequired</code> marks the mandatory ones.</p><p>Send the selections as <code>customizableOptions</code> — a map of option <code>id</code> → an <strong>array</strong> of chosen value <code>id</code>s:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customizableOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;9&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;10&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>Option <code>9</code> (Weight) → value <code>9</code> (1kg); option <code>10</code> (Flavour) → value <code>12</code> (Pineapple). The array form supports multi-select; for a text/textarea option the array holds the entered string. Include every option whose <code>isRequired</code> is <code>true</code>, or the request returns <code>422</code>. The chosen values come back on the cart item&#39;s <code>options</code> so you can show them on the cart page.</p><h4 id="file-type-customizable-options" tabindex="-1">File-type customizable options <a class="header-anchor" href="#file-type-customizable-options" aria-label="Permalink to &quot;File-type customizable options&quot;">​</a></h4><p>A <code>file</code>-type option needs a file upload, which cannot travel in a JSON body. Upload the file first at <strong><a href="/api/rest-api/shop/cart/upload-customizable-file.html">Upload Customizable File</a></strong> (a separate REST call that returns a token), then send the token here as that option&#39;s value:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customizableOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;9&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;10&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;11&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;upload-token&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>The full flow, endpoint, and rules are on the <a href="/api/rest-api/shop/cart/upload-customizable-file.html">Upload Customizable File</a> page.</p><blockquote><p>Use the example dropdown (top-right) to see the exact body for each product type.</p></blockquote><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p>On success the endpoint returns the <strong>full updated cart</strong> (HTTP 200), not just the added line. Key fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Cart ID</td></tr><tr><td><code>itemsCount</code></td><td>integer</td><td>Number of line items</td></tr><tr><td><code>items</code></td><td>array</td><td>Cart line items (each with <code>productId</code>, <code>name</code>, <code>quantity</code>, <code>type</code>, <code>options</code>, <code>formattedTotal</code>, …)</td></tr><tr><td><code>subtotal</code> / <code>grandTotal</code></td><td>decimal</td><td>Cart totals (raw)</td></tr><tr><td><code>formattedSubtotal</code> / <code>formattedGrandTotal</code></td><td>string</td><td>Localised, currency-formatted totals</td></tr><tr><td><code>couponCode</code></td><td>string|null</td><td>Applied coupon, if any</td></tr><tr><td><code>success</code></td><td>boolean</td><td>Whether the add succeeded</td></tr><tr><td><code>message</code></td><td>string</td><td>Human-readable result</td></tr></tbody></table><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li>If the same product (same options) is already in the cart, its quantity is increased.</li><li>Stock and saleability are validated; an inactive/out-of-stock item is rejected.</li><li>Booking products are added through the booking-specific flow, not this endpoint.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/create-cart.html">Create Cart</a> — get a guest cart token first</li><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a></li><li><a href="/api/rest-api/shop/cart/update-cart-item.html">Update Cart Item</a></li><li><a href="/api/rest-api/shop/cart/remove-cart-item.html">Remove Cart Item</a></li><li><a href="/api/rest-api/shop/cart/upload-customizable-file.html">Upload Customizable File</a> — stage a file-option file, then reference the token here</li><li><a href="/api/rest-api/shop/products/get-product.html">Get Product</a> — read a product&#39;s customizable options and supported file extensions</li></ul>',29)]))}const m=e(d,[["render",i]]);export{h as __pageData,m as default};
